r={'stage':'footplant_neutral_61_phase_audit','candidate_sha256':hashlib.sha256(a.blend.read_bytes()).hexdigest(),'sampled_frames':np.linspace(0,profile['periodFrames'],61).tolist(),'fps':profile['fps'],'period_frames':profile['periodFrames'],'phase_offsets_cycles':{n:v['stanceStartFrame']/profile['periodFrames'] for n,v in profile['limbs'].items()},'duty_factor':.6,'shared_speed_mps':profile['forwardSpeedMetersPerSecond'],'whole_body_max_stretch':worst,'collar_max_stretch':collarmax,'max_weight_sum_error':weight_error,'max_influences':influences,'loop_max_vertex_delta_root_relative_m':loop,'sole_summary':summary,'endpoint_target_max_error_m':endpoint,'endpoint_target_error_samples':rows,'metric_gates':gates,'accepted_cpu_neutral':all(gates.values()),'note':'Actual saved source skin evaluated at 61 phases. Chain endpoints are compared against the controlled distal bone heads; the animation is baked and no stale IK driver target is used. Collar is the subset x>0.1 and z>0.9. Includes one profile-speed actor translation only for stance slip.'};a.out.write_text(json.dumps(r,indent=2)+'\n');print(json.dumps({k:v for k,v in r.items() if k not in ('sampled_frames','endpoint_target_error_samples')},indent=2))

